#define CTF4b_IOCTL_WRITE 0x4B100
#define CTF4b_MSG_MAX_SIZE 0x100
#define CTF4b_DEV_NAME "ctf4b"
#define uint8_t unsigned char

struct ctf4b_request {
	char* buf;
	uint8_t size;
};

int fd;

void panic(const char *msg) {
    perror(msg);
    _exit(1);
}


int main() {
    fd = open("/dev/ctf4b", O_RDWR);
    if (fd < 0) {
        panic("Failed to open device");
    }

	struct ctf4b_request req = {
		.buf = NULL,
		.size = 0x10,
	};

	char buf[16] = {0};
	req.buf = buf;
    ioctl(fd, CTF4b_IOCTL_READ, &req);
	printf("[+] Module said: %s", buf);

	memset(buf, 0, sizeof(buf));
	ioctl(fd, CTF4b_IOCTL_READ, &req);
	printf("%s\n", buf);

	printf("[+] Writing to the module...\n");
	strcpy(buf, "Hello, CTF4b!!\x00");
	ioctl(fd, CTF4b_IOCTL_SEEK, 0);
	ioctl(fd, CTF4b_IOCTL_WRITE, &req);

	char recv_buf[16] = {0};
	req.buf = recv_buf;
	req.size = strlen(buf) - 2;
	ioctl(fd, CTF4b_IOCTL_SEEK, 0);
	ioctl(fd, CTF4b_IOCTL_READ, &req);
	printf("[+] Module said: %s\n", recv_buf);

    return 0;
}

